        .snippet-edit:hover { color: var(--accent-color); background: rgba(var(--accent-rgb, 99,102,241),0.12); }

        /* Bookmark subcommand inline buttons */
        .bm-subcmd-btn {
            display: inline-flex; align-items: center; justify-content: center;
            padding: 2px 8px; border-radius: 5px; font-size: 0.72rem; cursor: pointer;
