            background: none; border: 1px solid var(--border-color); border-radius: 4px;
            padding: 2px 5px; cursor: pointer; color: var(--text-secondary); display: flex;
            align-items: center; justify-content: center; transition: all 0.15s; height: 20px; width: 20px;
        }
        .sbicon-btn:hover { color: var(--text-primary); border-color: var(--accent-color); background: rgba(37,99,235,0.1); }
        .sbicon-btn.active { color: var(--accent-color); border-color: var(--accent-color); }
