// ── Quick Path Bar ────────────────────────────────────────────────────
const QUICK_PATH_STORAGE_KEY = 'quick-path-history';
const QUICK_PATH_MAX = 15;

function quickPathGetHistory() {
    try { return JSON.parse(localStorage.getItem(QUICK_PATH_STORAGE_KEY) || '[]'); }
    catch { return []; }
}

function quickPathSaveHistory(list) {
    localStorage.setItem(QUICK_PATH_STORAGE_KEY, JSON.stringify(list));
}

function quickPathAddEntry(path) {
    path = path.trim();
    if (!path) return;
    let list = quickPathGetHistory().filter(p => p.toLowerCase() !== path.toLowerCase());
    list.unshift(path);
    if (list.length > QUICK_PATH_MAX) list = list.slice(0, QUICK_PATH_MAX);
    quickPathSaveHistory(list);
}

function quickPathRemoveEntry(path) {
    const list = quickPathGetHistory().filter(p => p !== path);
    quickPathSaveHistory(list);
    renderQuickPathDropdown();
}

function renderQuickPathDropdown(filter = '') {
    const listEl = document.getElementById('quick-path-history-list');
    const emptyEl = document.getElementById('quick-path-empty');
    if (!listEl) return;
    listEl.innerHTML = '';
    const history = quickPathGetHistory();
    const filtered = filter ? history.filter(p => p.toLowerCase().includes(filter.toLowerCase())) : history;
    if (filtered.length === 0) {
        emptyEl.style.display = 'block';
    } else {
        emptyEl.style.display = 'none';
        filtered.forEach(p => {
            const item = document.createElement('div');
            item.className = 'quick-path-history-item';
            const pathEsc = p.replace(/"/g, '&quot;');
            item.innerHTML = `
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;opacity:0.5;"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg>
                <span title="${pathEsc}">${pathEsc}</span>
                <button class="quick-path-remove-btn" title="Remove" onclick="event.stopPropagation();quickPathRemoveEntry('${p.replace(/\\/g,'\\\\').replace(/'/g,"\\'")}')">✕</button>
            `;
            item.addEventListener('click', () => quickPathNavigateTo(p));
            listEl.appendChild(item);
        });
    }
}

function openQuickPathDropdown() {
    const dd = document.getElementById('quick-path-dropdown');
    if (!dd) return;
    renderQuickPathDropdown(document.getElementById('quick-path-input').value);
    dd.style.display = 'flex';
    dd.style.flexDirection = 'column';
}

function closeQuickPathDropdown() {
    const dd = document.getElementById('quick-path-dropdown');
    if (dd) dd.style.display = 'none';
}

function toggleQuickPathDropdown(e) {
    e && e.stopPropagation();
    const dd = document.getElementById('quick-path-dropdown');
    if (!dd) return;
    if (dd.style.display === 'none' || !dd.style.display) {
        openQuickPathDropdown();
    } else {
        closeQuickPathDropdown();
    }
}

function quickPathOnFocus() {
    document.getElementById('quick-path-input-wrap').style.borderColor = 'var(--accent-color)';
    openQuickPathDropdown();
}

function quickPathOnBlur() {
    // Delay so clicks inside dropdown register first
    setTimeout(() => {
        const dd = document.getElementById('quick-path-dropdown');
        if (dd && !dd.matches(':hover')) {
            closeQuickPathDropdown();
        }
        document.getElementById('quick-path-input-wrap').style.borderColor = '';
    }, 180);
}

function quickPathOnInput(e) {
    renderQuickPathDropdown(e.target.value);
    if (document.getElementById('quick-path-dropdown').style.display === 'none') {
        openQuickPathDropdown();
    }
}

function quickPathOnKeydown(e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        const path = e.target.value.trim();
        if (path) {
            quickPathNavigateTo(path);
        }
    } else if (e.key === 'Escape') {
        closeQuickPathDropdown();
        e.target.blur();
    }
}

async function quickPathNavigateTo(path) {
    if (!path || !activeProject) return;
    closeQuickPathDropdown();
    document.getElementById('quick-path-input').value = path;
    quickPathAddEntry(path);
    // Send cd command to active terminal
    const activePane = terminalPanes.find(p => p.socket === socket);
    const paneId = activePane ? activePane.paneId : 'main';
    await executeCommandMacro(activeProject, paneId, `cd "${path}"`, socket);
}

// Close quick path dropdown on outside click
document.addEventListener('click', (e) => {
    const bar = document.getElementById('quick-path-bar');
    if (bar && !bar.contains(e.target)) {
        closeQuickPathDropdown();
    }
});

// ── Bookmark Sub-commands ─────────────────────────────────────────────

