                    </div>
                `).join('');
            }
        } else {
            filesEl.innerHTML = '<div style="padding: 10px 14px; color: #ef4444; font-size: 0.8rem;">Failed to load changed files.</div>';
        }
    } catch (e) {
        filesEl.innerHTML = '<div style="padding: 10px 14px; color: #ef4444; font-size: 0.8rem;">Error loading files.</div>';
    }
}

