// ── Git Auto-Exclude Patterns ─────────────────────────────────────────
const GIT_EXCLUDE_KEY = 'git-auto-exclude-patterns';

function gitExcludeGetPatterns() {
    try { return JSON.parse(localStorage.getItem(GIT_EXCLUDE_KEY) || '[]'); }
    catch { return []; }
}

function gitExcludeSavePatterns(list) {
    localStorage.setItem(GIT_EXCLUDE_KEY, JSON.stringify(list));
}

function gitExcludeMatches(filePath, patterns) {
    const name = filePath.replace(/\\/g, '/').split('/').pop();
    return patterns.some(pat => {
        pat = pat.trim();
        if (!pat) return false;
        if (pat.startsWith('*.')) {
            return name.endsWith(pat.slice(1));  // *.json → .json
        }
        return name === pat || filePath.endsWith(pat);
    });
}

function renderGitExcludeList() {
    const list = gitExcludeGetPatterns();
    const el = document.getElementById('git-exclude-list');
    if (!el) return;
    if (list.length === 0) {
        el.innerHTML = '<div style="font-size:0.72rem;color:var(--text-muted);padding:2px 0;">No patterns yet.</div>';
        return;
    }
    el.innerHTML = list.map((p, i) => `
        <div style="display:flex;align-items:center;gap:6px;padding:3px 6px;background:var(--bg-main);border-radius:5px;border:1px solid var(--border-color);">
            <span style="flex:1;font-size:0.75rem;font-family:'JetBrainsMono NFP','JetBrains Mono','Fira Code',monospace;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${p}</span>
            <button onclick="removeGitExcludePattern(${i})" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:0.75rem;padding:1px 3px;border-radius:3px;line-height:1;flex-shrink:0;" onmouseenter="this.style.color='#f87171'" onmouseleave="this.style.color='var(--text-muted)'">✕</button>
        </div>
    `).join('');
}

function addGitExcludePattern() {
    const input = document.getElementById('git-exclude-input');
    const val = (input.value || '').trim();
    if (!val) return;
    const list = gitExcludeGetPatterns();
    if (!list.includes(val)) {
        list.push(val);
        gitExcludeSavePatterns(list);
    }
    input.value = '';
    renderGitExcludeList();
}

function removeGitExcludePattern(idx) {
    const list = gitExcludeGetPatterns();
    list.splice(idx, 1);
    gitExcludeSavePatterns(list);
    renderGitExcludeList();
}

