def _apply_statusbar_style(self):
    sb = self._config.get("statusbar", {}); bg, border_color, border_px = sb.get("bg", CP_BG) or CP_BG, sb.get("border_color", CP_RED) or CP_RED, int(sb.get("border_px", 1))
